	public FeatureRestController( FeatureService service ) {
		this.service = service;
	}
    /**
     * Handles create a Feature.  if not key provided, calls create, otherwise calls save
     * @param		Feature	feature
     * @return		Feature 
     */
	@PostMapping("/create")
    public Feature create( @RequestBody(required=true) CreateFeatureCommand command ) {
    	Feature entity = null;
		try {       
        	
			entity = service.createFeature( command );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage(), exc );        	
        }
		
		return entity;
    }

    /**
     * Handles updating a Feature.  if no key provided, calls create, otherwise calls save
     * @param		Feature feature
     * @return		Feature
     */
	@PutMapping("/update")
    public Feature update( @RequestBody(required=true) UpdateFeatureCommand command ) {
		Feature entity = null;
		try {                        	        
			// -----------------------------------------------
			// delegate the UpdateFeatureCommand
			// -----------------------------------------------
			entity = service.updateFeature(command);;
	    }
	    catch( Throwable exc ) {
	    	LOGGER.log( Level.WARNING, "FeatureController:update() - successfully update Feature - " + exc.getMessage());        	
	    }		
		
		return entity;
	}
 
    /**
     * Handles deleting a Feature entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeleteFeatureCommand command ) {                
    	try {
        	FeatureService delegate = service;

        	delegate.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted Feature with key " + command.getFeatureId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }

	}        
	
    /**
     * Handles loading a Feature using a UUID
     * @param		UUID uuid 
     * @return		Feature
     */    
    @GetMapping("/load")
    public Feature load( @RequestParam(required=true) UUID uuid ) {    	
    	Feature entity = null;

    	try {  
    		entity = service.getFeature( new FeatureFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Feature using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Feature business objects
     * @return		Set<Feature>
     */
    @GetMapping("/")
    public List<Feature> loadAll() {                
    	List<Feature> featureList = null;
        
    	try {
            // load the Feature
            featureList = service.getAllFeature();
            
            if ( featureList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Features" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Features ", exc );
        	return null;
        }

        return featureList;
                            
    }

